A `Vec` starts empty. After this loop, what are `v.size` and `v.cap`, assuming every `realloc` succeeds?

```c
#include <stdio.h>
#include <stdlib.h>
typedef struct { int *data; size_t size, cap; } Vec;
void vec_push(Vec *v, int x) {
    if (v->size == v->cap) {
        v->cap = v->cap ? 2 * v->cap : 4;
        v->data = realloc(v->data, v->cap * sizeof *v->data);
    }
    v->data[v->size++] = x;
}
int main(void) {
    Vec v = {0};
    for (int i = 0; i < 10; i++) vec_push(&v, i);
    printf("%zu %zu\n", v.size, v.cap);
}
```

What does this program print? `balanced` uses a **stack** of up to 16 characters.

```c
#include <stdbool.h>
#include <stdio.h>
bool balanced(const char *s) {
    char st[16]; int top = 0;
    for (; *s; s++) {
        if (*s == '(' || *s == '[') { if (top == 16) return false; st[top++] = *s; }
        else if (*s == ')' || *s == ']') {
            if (top == 0) return false;
            char open = st[--top];
            if (open != (*s == ')' ? '(' : '[')) return false;
        }
    }
    return top == 0;
}
int main(void) { printf("%d%d%d\n", balanced("([])"), balanced("([)]"), balanced("(()")); }
```

What does this program print? `put` returns 1 if it stored the item and 0 if the buffer was full.

```c
#include <stdio.h>
#define N 4
static int buf[N];
static unsigned head, tail;   /* head: next write, tail: next read */
int put(int x) { unsigned nh = (head + 1) % N; if (nh == tail) return 0; buf[head] = x; head = nh; return 1; }
int get(int *x) { if (head == tail) return 0; *x = buf[tail]; tail = (tail + 1) % N; return 1; }
int main(void) {
    int ok = 0, v = 0;
    for (int i = 1; i <= 5; i++) ok += put(i * 10);
    get(&v); get(&v);
    ok += put(60);
    printf("%d %d\n", ok, v);
}
```

What does this program print? `uint8_t` is 8 bits wide, so `head++` wraps from 255 to 0.

```c
#include <stdint.h>
#include <stdio.h>
#define N 8u
int main(void) {
    uint8_t head = 254;
    for (int i = 0; i < 4; i++) {
        printf("%u ", head & (N - 1));
        head++;
    }
    printf("\n");
}
```

The interrupt handler `uart_isr` stores each received byte, and `main_get` waits for one. Compiled with `-O2`, the loop in `main_get` may never finish. What small change to the declarations fixes it?

```c
#include <stdint.h>
#define N 16u
static uint8_t buf[N];
static uint8_t head, tail;   /* head: written by the ISR; tail: by main */
void uart_isr(uint8_t byte) { buf[head & (N - 1)] = byte; head++; }
uint8_t main_get(void) {
    while (head == tail) { }          /* wait for data */
    return buf[tail++ & (N - 1)];
}
```

This string hash adds up the character codes and reduces them to a table of 8 slots. What does the program print?

```c
#include <stdio.h>
unsigned hash(const char *s) {
    unsigned sum = 0;
    while (*s) sum += (unsigned char)*s++;
    return sum % 8;
}
int main(void) {
    printf("%u %u %u\n", hash("abc"), hash("cab"), hash("bad"));
    return 0;
}
```

With **separate chaining**, each bucket holds a linked list of the keys that landed there. What does this program print? (Nodes are never freed, to keep it short.)

```c
#include <stdio.h>
#include <stdlib.h>
#define N 4
typedef struct E { int key; struct E *next; } E;
static E *table[N];
void insert(int k) { E *e = malloc(sizeof *e); e->key = k; e->next = table[k % N]; table[k % N] = e; }
int contains(int k) { for (E *e = table[k % N]; e; e = e->next) if (e->key == k) return 1; return 0; }
int main(void) {
    int keys[] = {5, 9, 2, 13};
    for (int i = 0; i < 4; i++) insert(keys[i]);
    for (E *e = table[1]; e; e = e->next) printf("%d ", e->key);
    printf("| %d %d\n", contains(9), contains(17));
}
```

With **linear probing**, a key that finds its slot taken tries the next slot, wrapping from the last slot to 0. Which slots do the four keys land in?

```c
#include <stdio.h>
#define N 8
static int slot[N], used[N];
int insert(int key) {
    int i = key % N;
    while (used[i]) i = (i + 1) % N;
    used[i] = 1; slot[i] = key;
    return i;
}
int main(void) {
    int keys[] = {3, 11, 19, 4};
    for (int k = 0; k < 4; k++) printf("%d ", insert(keys[k]));
    printf("\n");
    return 0;
}
```

The **load factor** of a hash table is (items stored) ÷ (number of buckets). This code should print the load factor for 6 items in 8 buckets. What does it print, and why?

```c
#include <stdio.h>
int main(void) {
    int count = 6, size = 8;
    double load = count / size;
    printf("%.2f\n", load);
    return 0;
}
```

This binary search runs on a sorted array of 10 items. What does the program print?

```c
#include <stdio.h>
int find(const int *a, int n, int key) {
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = lo + (hi - lo) / 2;
        printf("%d ", mid);
        if (a[mid] == key) return mid;
        if (a[mid] < key) lo = mid + 1; else hi = mid - 1;
    }
    return -1;
}
int main(void) {
    int a[] = {2, 5, 8, 12, 16, 23, 38, 56, 72, 91};
    printf("-> %d\n", find(a, 10, 23));
}
```

**Insertion sort** keeps the front of the array sorted and slides each new item left into place. How many shifts (executions of `a[j + 1] = a[j]`) does this program count on a reversed input?

```c
#include <stdio.h>
int main(void) {
    int a[] = {5, 4, 3, 2, 1}, shifts = 0;
    for (int i = 1; i < 5; i++) {
        int key = a[i], j = i - 1;
        while (j >= 0 && a[j] > key) { a[j + 1] = a[j]; j--; shifts++; }
        a[j + 1] = key;
    }
    printf("%d\n", shifts);
    return 0;
}
```

**Quicksort**'s **partition** step rearranges a range around a chosen *pivot*: items at most the pivot go before it, larger items after it. Here the pivot is the last item. What does the program print?

```c
#include <stdio.h>
int partition(int *a, int lo, int hi) {
    int pivot = a[hi], i = lo - 1;
    for (int j = lo; j < hi; j++)
        if (a[j] <= pivot) { i++; int t = a[i]; a[i] = a[j]; a[j] = t; }
    int t = a[i + 1]; a[i + 1] = a[hi]; a[hi] = t;
    return i + 1;
}
int main(void) {
    int a[] = {3, 8, 2, 5, 1, 4};
    int p = partition(a, 0, 5);
    printf("%d:", p);
    for (int i = 0; i < 6; i++) printf(" %d", a[i]);
    printf("\n");
}
```

What does this program print? `inorder` is an **in-order traversal**: visit the left subtree, then the node, then the right subtree. Both `insert` and `inorder` are **recursive**: they call themselves on a smaller part of the tree. Nodes come from a static pool, not `malloc`.

```c
#include <stdio.h>
typedef struct Node { int key; struct Node *left, *right; } Node;
static Node pool[8]; static int used;
Node *insert(Node *t, int k) {
    if (!t) { t = &pool[used++]; t->key = k; return t; }
    if (k < t->key) t->left = insert(t->left, k); else t->right = insert(t->right, k);
    return t;
}
void inorder(const Node *t) {
    if (t) { inorder(t->left); printf("%d ", t->key); inorder(t->right); }
}
int main(void) {
    Node *r = NULL; int k[] = {50, 30, 70, 20, 40};
    for (int i = 0; i < 5; i++) r = insert(r, k[i]);
    inorder(r); }
```

The tree below is a perfectly balanced BST of 7 keys. `visited` counts the nodes the search looks at. What does the program print?

```c
#include <stdio.h>
typedef struct Node { int key; const struct Node *left, *right; } Node;
static const Node n20 = {20, NULL, NULL}, n40 = {40, NULL, NULL}, n60 = {60, NULL, NULL}, n80 = {80, NULL, NULL};
static const Node n30 = {30, &n20, &n40}, n70 = {70, &n60, &n80};
static const Node root = {50, &n30, &n70};
int visited(const Node *t, int key) {
    int n = 0;
    while (t) {
        n++;
        if (key == t->key) break;
        t = key < t->key ? t->left : t->right;
    }
    return n;
}
int main(void) { printf("%d %d\n", visited(&root, 60), visited(&root, 45)); return 0; }
```

**Height** counts links on the longest downward path (an empty tree has height −1). What does this program print for a tree whose 5 nodes each have only a right child?

```c
#include <stdio.h>
typedef struct Node { int key; const struct Node *left, *right; } Node;
static const Node n5 = {5, NULL, NULL}, n4 = {4, NULL, &n5}, n3 = {3, NULL, &n4};
static const Node n2 = {2, NULL, &n3}, n1 = {1, NULL, &n2};
int height(const Node *t) {
    if (!t) return -1;
    int l = height(t->left), r = height(t->right);
    return 1 + (l > r ? l : r);
}
int main(void) { printf("%d\n", height(&n1)); return 0; }
```

This function should free every node of a tree. What goes wrong, and how do you fix it?

```c
#include <stdlib.h>
typedef struct Node { struct Node *left, *right; } Node;
void release(Node *t) {
    if (!t) return;
    free(t);
    release(t->left);
    release(t->right);
}
int main(void) {
    Node *root = calloc(1, sizeof *root);
    root->left = calloc(1, sizeof *root);
    release(root);
    return 0;
}
```

cards.body:
`free(t)` runs before `t->left` and `t->right` are read: a use-after-free. Free the children first, then the node itself.

Fix:

```c
release(t->left);
release(t->right);
free(t);
```

Why: Once `t` is freed, the fields inside it are gone. AddressSanitizer flags the read of `t->left` as `heap-use-after-free`. The corrected order is called post-order: children before parent.

Watch out: Skipping the recursion and calling only `free(root)` is the opposite mistake: it leaks every other node, because nothing else points to them any more.

cards.title:
`push` appends the item at the end of the array and then does **sift-up**: swap it with its parent while the parent is larger. What does this program print?

```c
#include <stdio.h>
static int h[8], n;
void push(int x) {
    int i = n++;
    h[i] = x;
    for (int p; i > 0 && h[p = (i - 1) / 2] > h[i]; i = p) {
        int t = h[p]; h[p] = h[i]; h[i] = t;
    }
}
int main(void) {
    int in[] = {5, 3, 8, 1};
    for (int k = 0; k < 4; k++) push(in[k]);
    for (int k = 0; k < n; k++) printf("%d ", h[k]);
}
```

`pop` removes the minimum: it moves the last item to the root and does **sift-down**: swap with the smaller child while that child is smaller. What does this program print?

```c
#include <stdio.h>
static int h[] = {1, 3, 8, 5, 9, 10}, n = 6;
int pop(void) {
    int top = h[0], i = 0;
    h[0] = h[--n];
    for (int c; (c = 2 * i + 1) < n; i = c) {
        if (c + 1 < n && h[c + 1] < h[c]) c++;
        if (h[i] <= h[c]) break;
        int t = h[i]; h[i] = h[c]; h[c] = t;
    }
    return top;
}
int main(void) {
    printf("%d |", pop());
    for (int k = 0; k < n; k++) printf(" %d", h[k]); }
```

This `sift_down` should restore the min-heap property after the root of $[9, 3, 2]$ is replaced. What does the program print, and what is wrong?

```c
#include <stdio.h>
static int h[] = {9, 3, 2}, n = 3;
void sift_down(int i) {
    for (;;) {
        int c = 2 * i + 1;            /* left child */
        if (c >= n || h[i] <= h[c]) break;
        int t = h[i]; h[i] = h[c]; h[c] = t;
        i = c;
    }
}
int main(void) { sift_down(0); printf("%d %d %d\n", h[0], h[1], h[2]); return 0; }
```

This BFS starts at vertex 0 of an undirected graph given as an adjacency matrix. What order does it print?

```c
#include <stdio.h>
#define V 5
static const int adj[V][V] = {          /* undirected: 0-1, 0-2, 1-4, 2-3, 3-4 */
    {0,1,1,0,0}, {1,0,0,0,1}, {1,0,0,1,0}, {0,0,1,0,1}, {0,1,0,1,0}};
int main(void) {
    int queue[V], head = 0, tail = 0, seen[V] = {0};
    queue[tail++] = 0; seen[0] = 1;
    while (head < tail) {
        int u = queue[head++];
        printf("%d ", u);
        for (int v = 0; v < V; v++)
            if (adj[u][v] && !seen[v]) { seen[v] = 1; queue[tail++] = v; }
    }
}
```

This DFS runs from vertex 0 on the same graph as the previous BFS card (edges 0–1, 0–2, 1–4, 2–3, 3–4), stored here as neighbor lists in increasing order. What order does it print?

```c
#include <stdio.h>
static const int deg[5] = {2, 2, 2, 2, 2};
static const int nbr[5][2] = {{1, 2}, {0, 4}, {0, 3}, {2, 4}, {1, 3}};
static int seen[5];
void dfs(int u) {
    seen[u] = 1;
    printf("%d ", u);
    for (int k = 0; k < deg[u]; k++)
        if (!seen[nbr[u][k]]) dfs(nbr[u][k]);
}
int main(void) { dfs(0); return 0; }
```

**Kahn's algorithm** repeatedly takes a vertex whose in-degree (number of incoming edges) is 0, outputs it and lowers its successors' in-degrees. What does this program print for the edges 3→1, 3→4, 0→4, 4→2, 1→2, 5→0?

```c
#include <stdio.h>
#define V 6
int main(void) {
    int from[] = {3, 3, 0, 4, 1, 5}, to[] = {1, 4, 4, 2, 2, 0}, E = 6;
    int indeg[V] = {0}, q[V], head = 0, tail = 0;
    for (int e = 0; e < E; e++) indeg[to[e]]++;
    for (int v = 0; v < V; v++) if (indeg[v] == 0) q[tail++] = v;
    while (head < tail) {
        int u = q[head++];
        printf("%d ", u);
        for (int e = 0; e < E; e++)
            if (from[e] == u && --indeg[to[e]] == 0) q[tail++] = to[e];
    }
}
```

Kahn's algorithm can also detect cycles: if it outputs fewer than $V$ vertices, the rest are stuck behind a cycle. What does this program print for the edges 0→1, 1→2, 2→1, 2→3?

```c
#include <stdio.h>
#define V 4
int main(void) {
    int from[] = {0, 1, 2, 2}, to[] = {1, 2, 1, 3}, E = 4;
    int indeg[V] = {0}, q[V], head = 0, tail = 0;
    for (int e = 0; e < E; e++) indeg[to[e]]++;
    for (int v = 0; v < V; v++) if (indeg[v] == 0) q[tail++] = v;
    while (head < tail) {
        int u = q[head++];
        for (int e = 0; e < E; e++)
            if (from[e] == u && --indeg[to[e]] == 0) q[tail++] = to[e];
    }
    printf("%d of %d: %s\n", tail, V, tail == V ? "DAG" : "cycle");
}
```
